// lib/python/bytes.mjs
//
// A `bytes`-like value is modelled as a plain JavaScript array of integers in
// the range 0..255.  These helpers cover the handful of `bytes` operations the
// program needs.

/** Number of leading occurrences of `byteValue`. */
export function countLeading(bytes, byteValue) {
  let n = 0;
  while (n < bytes.length && bytes[n] === byteValue) n += 1;
  return n;
}

/** Equivalent of `bytes.lstrip(single_byte)`. */
export function lstripByte(bytes, byteValue) {
  return bytes.slice(countLeading(bytes, byteValue));
}

/** `bytes([value] * count)`. */
export function repeatByte(byteValue, count) {
  const out = [];
  for (let i = 0; i < count; i += 1) out.push(byteValue);
  return out;
}

/** Concatenation of any number of byte arrays. */
export function concatBytes(...parts) {
  const out = [];
  for (const part of parts) {
    for (const value of part) out.push(value);
  }
  return out;
}

/** Byte values of an ASCII-only JavaScript string. */
export function bytesFromAscii(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) out.push(text.charCodeAt(i));
  return out;
}

/** Interpret ASCII byte values as a JavaScript string. */
export function asciiFromBytes(bytes) {
  let out = '';
  for (const value of bytes) out += String.fromCharCode(value);
  return out;
}
